# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">ESMÂ-İ HÜSNÂ: EL-HÂDÎ, ES-SELÂM VE EL-VEKÎL</text>\n  <rect x="30" y="50" width="200" height="185" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="130" y="75" text-anchor="middle" font-size="14" font-weight="bold" fill="#1d4ed8">El-Hâdî (الْهَادِي)</text>\n  <text x="45" y="105" font-size="11.5" fill="#334155">• Hidayet veren, doğru ve</text>\n  <text x="55" y="123" font-size="11" fill="#475569">gerçek yolu gösteren.</text>\n  <text x="45" y="150" font-size="11.5" fill="#334155">• Akıl, vahiy ve peygamberler</text>\n  <text x="55" y="168" font-size="11" fill="#475569">ile kullarını aydınlatan.</text>\n  <text x="130" y="212" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">&quot;Bizi dosdoğru yola ilet!&quot;</text>\n  <rect x="250" y="50" width="200" height="185" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="350" y="75" text-anchor="middle" font-size="14" font-weight="bold" fill="#15803d">Es-Selâm (السَّلَامُ)</text>\n  <text x="265" y="105" font-size="11.5" fill="#334155">• Her türlü eksiklik ve</text>\n  <text x="275" y="123" font-size="11" fill="#475569">kusurdan uzak olan.</text>\n  <text x="265" y="150" font-size="11.5" fill="#334155">• Kullarını tehlikelerden</text>\n  <text x="275" y="168" font-size="11" fill="#475569">selamete çıkaran, barış kaynağı.</text>\n  <text x="350" y="212" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">&quot;Allâhümme ente\'s-selâm...&quot;</text>\n  <rect x="470" y="50" width="200" height="185" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="570" y="75" text-anchor="middle" font-size="14" font-weight="bold" fill="#a16207">El-Vekîl (الْوَكِيلُ)</text>\n  <text x="485" y="105" font-size="11.5" fill="#334155">• Kendisine güvenip</text>\n  <text x="495" y="123" font-size="11" fill="#475569">dayananların işlerini en</text>\n  <text x="495" y="140" font-size="11" fill="#475569">güzel şekilde yoluna koyan.</text>\n  <text x="485" y="168" font-size="11.5" fill="#334155">• Tevekkül edilen tek dost.</text>\n  <text x="570" y="212" text-anchor="middle" font-size="11" font-weight="bold" fill="#b45309">&quot;Hasbünallâhu ve ni\'me\'l-vekîl&quot;</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">GÜZEL İSİMLERİN MÜSLÜMANIN AHLAK VE HAYATINA YANSIMALARI</text>\n  <rect x="35" y="50" width="300" height="185" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="185" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Hâdî ve Selâm İsimlerinin Yansıması</text>\n  <text x="50" y="105" font-size="11.5" fill="#334155">• Hâdî ismine inanan mümin; Kur\'an ve Sünnet</text>\n  <text x="62" y="123" font-size="11" fill="#475569">rehberliğinde sırat-ı müstakim üzere yaşar,</text>\n  <text x="62" y="140" font-size="11" fill="#475569">çevresine iyilikte rehber ve örnek olur.</text>\n  <text x="50" y="168" font-size="11.5" fill="#334155">• Selâm ismine inanan mümin; elinden ve</text>\n  <text x="62" y="186" font-size="11" fill="#475569">dilinden herkesin güvende olduğu barış insanıdır,</text>\n  <text x="62" y="204" font-size="11" fill="#475569">&quot;es-Selâmü aleyküm&quot; diyerek esenlik yayar.</text>\n  <rect x="365" y="50" width="300" height="185" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="515" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Vekîl İsminin Yansıması: Tevekkül</text>\n  <text x="380" y="105" font-size="11.5" fill="#334155">• Vekîl ismini kavrayan mümin; üzerine düşen</text>\n  <text x="392" y="123" font-size="11" fill="#475569">tüm hazırlık, çalışma ve tedbiri eksiksiz yapar.</text>\n  <text x="380" y="150" font-size="11.5" fill="#334155">• Sonucu Yüce Allah\'a havale ederek ümitsizlik</text>\n  <text x="392" y="168" font-size="11" fill="#475569">ve aşırı kaygıdan kurtulur, iç huzura kavuşur.</text>\n  <text x="380" y="195" font-size="11.5" fill="#334155">• Kendisine güvenen insanları yarı yolda</text>\n  <text x="392" y="213" font-size="11" fill="#475569">bırakmaz, emanet ve sorumluluklarını korur.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">KUR\'AN-I KERİM\'DE HÂDÎ, SELÂM VE VEKÎL İSİMLERİ</text>\n  <rect x="30" y="55" width="200" height="175" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="130" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Furkan Suresi, 31. Ayet</text>\n  <text x="130" y="115" text-anchor="middle" font-size="11.5" fill="#334155">&quot;...Yol gösterici (Hâdî)</text>\n  <text x="130" y="135" text-anchor="middle" font-size="11.5" fill="#334155">ve yardımcı olarak</text>\n  <text x="130" y="155" text-anchor="middle" font-size="11.5" fill="#334155">Rabbin yeter!&quot;</text>\n  <text x="130" y="198" text-anchor="middle" font-size="11" font-weight="bold" fill="#b45309">Hidayet Kaynağı: El-Hâdî</text>\n  <rect x="250" y="55" width="200" height="175" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="350" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Haşr Suresi, 23. Ayet</text>\n  <text x="350" y="115" text-anchor="middle" font-size="11.5" fill="#334155">&quot;O, kendisinden başka</text>\n  <text x="350" y="135" text-anchor="middle" font-size="11.5" fill="#334155">ilah olmayan Allah\'tır;</text>\n  <text x="350" y="155" text-anchor="middle" font-size="11.5" fill="#334155">Melik\'tir, Kuddûs\'tür,</text>\n  <text x="350" y="175" text-anchor="middle" font-size="11.5" fill="#334155">Selâm\'dır, Mü\'min\'dir...&quot;</text>\n  <text x="350" y="205" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">Esenlik Kaynağı: Es-Selâm</text>\n  <rect x="470" y="55" width="200" height="175" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="570" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Âl-i İmrân, 173. Ayet</text>\n  <text x="570" y="115" text-anchor="middle" font-size="11.5" fill="#334155">&quot;Allah bize yeter,</text>\n  <text x="570" y="135" text-anchor="middle" font-size="11.5" fill="#334155">O ne güzel vekildir!&quot;</text>\n  <text x="570" y="162" text-anchor="middle" font-size="10.5" fill="#475569">(Hasbünallâhu ve ni\'me\'l-vekîl)</text>\n  <text x="570" y="198" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">Güven Kaynağı: El-Vekîl</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
